import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand written PTX implementing a shared-memory tiled GEMM with thread-level
# register blocking:
#   C(M,N) = A(M,K) * B(K,N)   (row-major, standard PyTorch layout)
#
# CTA tile:  BM=64, BN=64, BK=16
# Block:     16x16 threads (256 threads)
# Each thread computes a 4x4 (TM x TN) register-blocked sub-tile of C,
# staged through shared memory (sA holds a 64x16 tile of A, sB holds a
# 16x64 tile of B). This amortizes shared-memory traffic over 16 FMAs per
# loaded operand pair instead of 1, improving arithmetic intensity and
# reducing shared-memory bandwidth pressure compared to a 1-output-per-
# thread kernel.
#
# Grid:  (N/64, M/64, 1)
# Block: (16, 16, 1)
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gemm_kernel(
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K,
    .param .u64 param_A,
    .param .u32 param_lda,
    .param .u64 param_B,
    .param .u32 param_ldb,
    .param .u64 param_C,
    .param .u32 param_ldc
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<200>;
    .reg .b64 %rd<60>;
    .reg .f32 %f<80>;

    .shared .align 16 .b8 sA[4096];
    .shared .align 16 .b8 sB[4352];

    ld.param.u32 %r1, [param_M];
    ld.param.u32 %r2, [param_N];
    ld.param.u32 %r3, [param_K];
    ld.param.u64 %rd1, [param_A];
    ld.param.u32 %r4, [param_lda];
    ld.param.u64 %rd2, [param_B];
    ld.param.u32 %r5, [param_ldb];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r6, [param_ldc];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r10, %tid.x;
    mov.u32 %r11, %tid.y;
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ctaid.y;

    // row0 = by*64 ; col0 = bx*64
    shl.b32 %r16, %r13, 6;
    shl.b32 %r17, %r12, 6;

    // tid_lin = ty*16 + tx
    shl.b32 %r18, %r11, 4;
    add.s32 %r18, %r18, %r10;

    // localRowBase = ty*4 ; localColBase = tx*4
    shl.b32 %r19, %r11, 2;
    shl.b32 %r20, %r10, 2;

    mov.u32 %r21, sA;
    mov.u32 %r22, sB;

    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;

    mov.u32 %r30, 0;   // k0

LOOP_K:
    setp.ge.s32 %p1, %r30, %r3;
    @%p1 bra LOOP_K_END;

    // ---------------- Load A tile: 64x16, vectorized float4 single pass ----------------
    // 256 threads * 4 elements = 1024 = 64*16; each thread loads one contiguous
    // float4 (row = tid_lin/4, colstart = (tid_lin%4)*4). shared offset = tid_lin*16 bytes.
    shr.u32 %r100, %r18, 2;
    and.b32 %r101, %r18, 3;
    shl.b32 %r102, %r101, 2;
    add.s32 %r103, %r16, %r100;
    add.s32 %r104, %r30, %r102;
    mad.lo.s32 %r105, %r103, %r4, %r104;
    mul.wide.s32 %rd20, %r105, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.v4.f32 {%f40, %f41, %f42, %f43}, [%rd21];
    shl.b32 %r150, %r102, 8;    // kRel*256 (transposed row stride bytes)
    shl.b32 %r151, %r100, 2;    // m*4 bytes
    add.s32 %r152, %r150, %r151;
    add.s32 %r153, %r21, %r152; // addr of sA_T[kRel][m]
    st.shared.f32 [%r153], %f40;
    add.s32 %r154, %r153, 256;
    st.shared.f32 [%r154], %f41;
    add.s32 %r155, %r153, 512;
    st.shared.f32 [%r155], %f42;
    add.s32 %r156, %r153, 768;
    st.shared.f32 [%r156], %f43;
    // ---------------- Load B tile: 16x64, vectorized float4 single pass ----------------
    // 256 threads * 4 elements = 1024 = 16*64; each thread loads one contiguous
    // float4 (row = tid_lin/16, colstart = (tid_lin%16)*4). shared offset = tid_lin*16 bytes.
    shr.u32 %r108, %r18, 4;
    and.b32 %r109, %r18, 15;
    shl.b32 %r110, %r109, 2;
    add.s32 %r111, %r30, %r108;
    add.s32 %r112, %r17, %r110;
    mad.lo.s32 %r113, %r111, %r5, %r112;
    mul.wide.s32 %rd22, %r113, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.v4.f32 {%f44, %f45, %f46, %f47}, [%rd23];
    mul.lo.s32 %r115, %r108, 272;   // row * padded_stride_bytes (68 floats * 4 bytes)
    shl.b32 %r116, %r110, 2;        // colstart_elems * 4 bytes
    add.s32 %r117, %r115, %r116;
    add.s32 %r114, %r22, %r117;
    st.shared.v4.f32 [%r114], {%f44, %f45, %f46, %f47};

    bar.sync 0;

    // ---------------- Inner reduction with 4x4 register blocking ----------------
    mov.u32 %r60, 0;
INNER_LOOP:
    setp.ge.s32 %p2, %r60, 16;
    @%p2 bra INNER_END;

    shl.b32 %r180, %r60, 8;     // kk*256 (transposed sA row stride bytes)
    shl.b32 %r181, %r19, 2;     // (ty*4)*4 bytes = mBase bytes
    add.s32 %r182, %r180, %r181;
    add.s32 %r183, %r21, %r182; // addr of {m,m+1,m+2,m+3} at fixed kk
    ld.shared.v4.f32 {%f50, %f51, %f52, %f53}, [%r183];

    mul.lo.s32 %r70, %r60, 68;   // kk*68 (padded stride, avoids bank conflicts)
    add.s32 %r71, %r70, %r20;   // + tx*4
    shl.b32 %r72, %r71, 2;      // *4 bytes
    add.s32 %r73, %r22, %r72;   // addr col j=0

    ld.shared.v4.f32 {%f60, %f61, %f62, %f63}, [%r73];

    fma.rn.f32 %f10, %f50, %f60, %f10;
    fma.rn.f32 %f11, %f50, %f61, %f11;
    fma.rn.f32 %f12, %f50, %f62, %f12;
    fma.rn.f32 %f13, %f50, %f63, %f13;

    fma.rn.f32 %f14, %f51, %f60, %f14;
    fma.rn.f32 %f15, %f51, %f61, %f15;
    fma.rn.f32 %f16, %f51, %f62, %f16;
    fma.rn.f32 %f17, %f51, %f63, %f17;

    fma.rn.f32 %f18, %f52, %f60, %f18;
    fma.rn.f32 %f19, %f52, %f61, %f19;
    fma.rn.f32 %f20, %f52, %f62, %f20;
    fma.rn.f32 %f21, %f52, %f63, %f21;

    fma.rn.f32 %f22, %f53, %f60, %f22;
    fma.rn.f32 %f23, %f53, %f61, %f23;
    fma.rn.f32 %f24, %f53, %f62, %f24;
    fma.rn.f32 %f25, %f53, %f63, %f25;

    add.s32 %r60, %r60, 1;
    bra INNER_LOOP;
INNER_END:

    bar.sync 0;

    add.s32 %r30, %r30, 16;
    bra LOOP_K;

LOOP_K_END:

    add.s32 %r83, %r16, %r19;   // base_row = row0 + ty*4
    add.s32 %r84, %r17, %r20;   // base_col = col0 + tx*4

    // i = 0
    add.s32 %r90, %r83, 0;
    add.s32 %r91, %r84, 0;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f10;

    add.s32 %r91, %r84, 1;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f11;

    add.s32 %r91, %r84, 2;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f12;

    add.s32 %r91, %r84, 3;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f13;

    // i = 1
    add.s32 %r90, %r83, 1;
    add.s32 %r91, %r84, 0;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f14;

    add.s32 %r91, %r84, 1;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f15;

    add.s32 %r91, %r84, 2;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f16;

    add.s32 %r91, %r84, 3;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f17;

    // i = 2
    add.s32 %r90, %r83, 2;
    add.s32 %r91, %r84, 0;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f18;

    add.s32 %r91, %r84, 1;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f19;

    add.s32 %r91, %r84, 2;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f20;

    add.s32 %r91, %r84, 3;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f21;

    // i = 3
    add.s32 %r90, %r83, 3;
    add.s32 %r91, %r84, 0;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f22;

    add.s32 %r91, %r84, 1;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f23;

    add.s32 %r91, %r84, 2;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f24;

    add.s32 %r91, %r84, 3;
    mad.lo.s32 %r92, %r90, %r6, %r91;
    mul.wide.s32 %rd40, %r92, 4;
    add.s64 %rd41, %rd3, %rd40;
    st.global.f32 [%rd41], %f25;

    ret;
}
"""

_ENTRY_NAME = "gemm_kernel"
_BLOCK = 16       # threads per dimension (16x16 = 256 threads per CTA)
_TILE_M = 64      # CTA output tile rows
_TILE_N = 64      # CTA output tile cols
_TILE_K = 16      # K-dimension chunk staged through shared memory

_module_cache = None


def _get_module() -> PtxModule:
    global _module_cache
    if _module_cache is None:
        _module_cache = PtxModule(PTX_SOURCE)
    return _module_cache


def validate_generated_code():
    """Compiles the embedded PTX and verifies the kernel entry is present."""
    module = _get_module()
    fn = module.function(_ENTRY_NAME)
    assert fn is not None, f"entry point '{_ENTRY_NAME}' not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A @ B implemented via a hand-written
    PTX tiled-GEMM kernel with 4x4 thread-level register blocking, executed
    through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self):
        super().__init__()
        self._module = None

    def _module_ref(self) -> PtxModule:
        if self._module is None:
            self._module = _get_module()
        return self._module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dim() == 2 and B.dim() == 2, "A and B must be 2D"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "expect float32"

        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "A.size(1) must equal B.size(0)"
        assert M % _TILE_M == 0 and N % _TILE_N == 0 and K % _TILE_K == 0, (
            f"M must be divisible by {_TILE_M}, N by {_TILE_N}, K by {_TILE_K}"
        )

        A_c = A.contiguous()
        B_c = B.contiguous()
        C = torch.empty((M, N), device=A.device, dtype=torch.float32)

        module = self._module_ref()

        grid = (N // _TILE_N, M // _TILE_M, 1)
        block = (_BLOCK, _BLOCK, 1)

        stream = torch.cuda.current_stream(device=A.device)

        kernel_args = [
            i32(M),
            i32(N),
            i32(K),
            u64(A_c.data_ptr()),
            i32(K),   # lda
            u64(B_c.data_ptr()),
            i32(N),   # ldb
            u64(C.data_ptr()),
            i32(N),   # ldc
        ]
        module.launch(
            _ENTRY_NAME,
            grid,
            block,
            kernel_args,
            stream=stream,
        )

        return C

