import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand written PTX implementing a shared-memory tiled GEMM with thread-level
# register blocking:
#   C(M,N) = A(M,K) * B(K,N)   (row-major, standard PyTorch layout)
#
# CTA tile:  BM=64, BN=64, BK=16
# Block:     16x16 threads (256 threads)
# Each thread computes a 4x4 (TM x TN) register-blocked sub-tile of C,
# staged through shared memory (sA holds a 64x16 tile of A, sB holds a
# 16x64 tile of B). This amortizes shared-memory traffic over 16 FMAs per
# loaded operand pair instead of 1, improving arithmetic intensity and
# reducing shared-memory bandwidth pressure compared to a 1-output-per-
# thread kernel.
#
# Grid:  (N/64, M/64, 1)
# Block: (16, 16, 1)
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gemm_kernel(
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K,
    .param .u64 param_A,
    .param .u32 param_lda,
    .param .u64 param_B,
    .param .u32 param_ldb,
    .param .u64 param_C,
    .param .u32 param_ldc
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<120>;
    .reg .b64 %rd<60>;
    .reg .f32 %f<80>;

    .shared .align 16 .b8 sA[4096];
    .shared .align 16 .b8 sB[4352];

    ld.param.u32 %r1, [param_M];
    ld.param.u32 %r2, [param_N];
    ld.param.u32 %r3, [param_K];
    ld.param.u64 %rd1, [param_A];
    ld.param.u32 %r4, [param_lda];
    ld.param.u64 %rd2, [param_B];
    ld.param.u32 %r5, [param_ldb];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r6, [param_ldc];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r10, %tid.x;
    mov.u32 %r11, %tid.y;
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ctaid.y;

    // row0 = by*64 ; col0 = bx*64
    shl.b32 %r16, %r13, 6;
    shl.b32 %r17, %r12, 6;

    // tid_lin = ty*16 + tx
    shl.b32 %r18, %r11, 4;
    add.s32 %r18, %r18, %r10;

    // localRowBase = ty*4 ; localColBase = tx*4
    shl.b32 %r19, %r11, 2;
    shl.b32 %r20, %r10, 2;

    mov.u32 %r21, sA;
    mov.u32 %r22, sB;

    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;

    mov.u32 %r30, 0;   // k0

LOOP_K:
    setp.ge.s32 %p1, %r30, %r3;
    @%p1 bra LOOP_K_END;

    // ---------------- Load A tile: 64x16, vectorized float4 single pass ----------------
    // 256 threads * 4 elements = 1024 = 64*16; each thread loads one contiguous
    // float4 (row = tid_lin/4, colstart = (tid_lin%4)*4). shared offset = tid_lin*16 bytes.
    shr.u32 %r100, %r18, 2;
    and.b32 %r101, %r18, 3;
    shl.b32 %r102, %r101, 2;
    add.s32 %r103, %r16, %r100;
    add.s32 %r104, %r30, %r102;
    mad.lo.s32 %r105, %r103, %r4, %r104;
    mul.wide.s32 %rd20, %r105, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.v4.f32 {%f40, %f41, %f42, %f43}, [%rd21];
    shl.b32 %r106, %r18, 4;
    add.s32 %r107, %r21, %r106;
    st.shared.v4.f32 [%r107], {%f40, %f41, %f42, %f43};
    // ---------------- Load B tile: 16x64, vectorized float4 single pass ----------------
    // 256 threads * 4 elements = 1024 = 16*64; each thread loads one contiguous
    // float4 (row = tid_lin/16, colstart = (tid_lin%16)*4). shared offset = tid_lin*16 bytes.
    shr.u32 %r108, %r18, 4;
    and.b32 %r109, %r18, 15;
    shl.b32 %r110, %r109, 2;
    add.s32 %r111, %r30, %r108;
    add.s32 %r112, %r17, %r110;
    mad.lo.s32 %r113, %r111, %r5, %r112;
    mul.wide.s32 %rd22, %r113, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.v4.f32 {%f44, %f45, %f46, %f47}, [%rd23];
    mul.lo.s32 %r115, %r108, 272;   // row * padded_stride_bytes (68 floats * 4 bytes)
    shl.b32 %r116, %r110, 2;        // colstart_elems * 4 bytes
    add.s32 %r117, %r115, %r116;
    add.s32 %r114, %r22, %r117;
    st.shared.v4.f32 [%r114], {%f44, %f45, %f46, %f47};

    bar.sync 0;

    // ---------------- Inner reduction with 4x4 register blocking ----------------
    mov.u32 %r60, 0;
INNER_LOOP:
    setp.ge.s32 %p2, %r60, 16;
    @%p2 bra INNER_END;

    shl.b32 %r61, %r19, 4;      // ty*4*16
    add.s32 %r62, %r61, %r60;   // + kk
    shl.b32 %r63, %r62, 2;      // *4 bytes
    add.s32 %r64, %r21, %r63;   // addr row i=0

    ld.shared.f32 %f50, [%r64];
    add.s32 %r65, %r64, 64;
    ld.shared.f32 %f51, [%r65];
    add.s32 %r66, %r64, 128;
    ld.shared.f32 %f52, [%r66];
    add.s32 %r67, %r64, 192;
    ld.shared.f32 %f53, [%r67];

    mul.lo.s32 %r70, %r60, 68;   // kk*68 (padded stride, avoids bank conflicts)
    add.s32 %r71, %r70, %r20;   // + tx*4
    shl.b32 %r72, %r71, 2;      // *4 bytes
