            i32(K),
            u64(A_c.data_ptr()),
            i32(K),   # lda
            u64(B_c.data_ptr()),
            i32(N),   # ldb
            u64(C.data_ptr()),
            i32(N),   # ldc
        ]
        module.launch(
            _ENTRY_NAME,
            grid,
            block,
            kernel_args,
            stream=stream,
        )

